export type BrandName = keyof typeof BRANDS;

/** Every brand in the set, by name. */
export const BRAND_NAMES = Object.keys(BRANDS) as BrandName[];

/** The brand's display name: "Stack Overflow". */
export const brandTitle = (name: BrandName) => BRANDS[name].title;

/** True for a brand color too close to black or white to show on both
 *  themes; those marks take the text color instead. */
function neutral(hex: string) {
  const n = parseInt(hex.slice(1), 16);
  const [r, g, b] = [(n >> 16) & 255, (n >> 8) & 255, n & 255].map((c) => {
    const v = c / 255;
    return v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4;
  });
  const l = 0.2126 * r + 0.7152 * g + 0.0722 * b;
  return l < 0.035 || l > 0.85;
}

/**
 * One brand's mark as an inline SVG, in its own color (or the text color
 * for black and white marks, so it reads in light and dark). Decorative:
 * name the service in the text beside it.
 */
export function BrandMark({ name, size = 16, mono = false, className }: { name: BrandName; size?: number; mono?: boolean; className?: string }) {
  const brand: Brand = BRANDS[name];
  if (name === "microsoft") {
    return (
      <svg viewBox="0 0 21 21" width={size} height={size} aria-hidden="true" className={className}>
        <rect width="10" height="10" fill={mono ? "currentColor" : "#F25022"} />
        <rect x="11" width="10" height="10" fill={mono ? "currentColor" : "#7FBA00"} />
        <rect y="11" width="10" height="10" fill={mono ? "currentColor" : "#00A4EF"} />
        <rect x="11" y="11" width="10" height="10" fill={mono ? "currentColor" : "#FFB900"} />
      </svg>
    );
  }
  const fill = mono || neutral(brand.hex) ? "currentColor" : brand.hex;
  return (
    <svg viewBox="0 0 24 24" width={size} height={size} aria-hidden="true" className={className} fill={fill}>
      <path d={brand.d} fillRule={"evenodd" in brand ? "evenodd" : undefined} />
    </svg>
  );
}
